import React, { useEffect, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import PostItem from '../components/PostItem';
import Pagination from '../components/Pagination';
import styled from 'styled-components';
import TagAutocomplete from '../components/TagAutocomplete';

const PageContainer = styled.div`
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem;
`;

const PageTitle = styled.h1`
    font-size: 2rem;
    color: #333;
    margin-bottom: 2rem;
    font-weight: 600;
`;

const SearchContainer = styled.div`
    margin: 1rem 0;
    display: flex;
    gap: 1rem;
    align-items: center;
`;

const PostsGrid = styled.div`
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 2rem;
`;

function BrandsPage() {
    const [searchParams, setSearchParams] = useSearchParams();
    const [posts, setPosts] = useState([]);
    const [searchTag, setSearchTag] = useState('');
    const [pagination, setPagination] = useState({
        currentPage: 1,
        totalPages: 1,
        totalItems: 0
    });

    useEffect(() => {
        const page = parseInt(searchParams.get('page')) || 1;
        const tag = searchParams.get('tag') || '';
        setSearchTag(tag);
        fetchPosts(page, tag);
    }, [searchParams]);

    async function fetchPosts(page = 1, tagValue = '') {
        try {
            let url = `/api/posts/brands?page=${page}`;
            if (tagValue) {
                url += `&tag=${encodeURIComponent(tagValue)}`;
            }

            const res = await fetch(url);
            const data = await res.json();
            setPosts(data.posts || []);
            setPagination({
                currentPage: data.currentPage,
                totalPages: data.totalPages,
                totalItems: data.totalItems
            });
        } catch (err) {
            console.error(err);
            setPosts([]);
        }
    }

    function handleSearch(e) {
        e.preventDefault();
        setSearchParams({ page: '1', ...(searchTag && { tag: searchTag }) });
    }

    const handlePageChange = (newPage) => {
        setSearchParams({ page: newPage.toString(), ...(searchTag && { tag: searchTag }) });
    };

    return (
        <PageContainer>
            <PageTitle>Brands</PageTitle>
            <SearchContainer>
                <SearchForm onSubmit={handleSearch}>
                    <SearchLabel>Search by tag:</SearchLabel>
                    <SearchInput
                        type="text"
                        value={searchTag}
                        onChange={e => setSearchTag(e.target.value)}
                        placeholder="Enter tag name..."
                    />
                    <SearchButton type="submit">
                        Search
                    </SearchButton>
                </SearchForm>
            </SearchContainer>

            <PostsGrid>
                {posts.map(post => (
                    <PostItem key={post.id} post={post} />
                ))}
            </PostsGrid>

            <Pagination 
                currentPage={pagination.currentPage}
                totalPages={pagination.totalPages}
                onPageChange={handlePageChange}
            />
        </PageContainer>
    );
}

export default BrandsPage;
